void channel_key_text(const meshtastic_ChannelSettings_psk_t& key,char* out){static const char hex[]="0123456789abcdef";for(unsigned i=0;i<key.size;++i){out[i*2]=hex[key.bytes[i]>>4];out[i*2+1]=hex[key.bytes[i]&15];}out[key.size*2]=0;}
bool channel_key_parse(const char* s,meshtastic_ChannelSettings_psk_t& out){auto n=std::strlen(s);meshtastic_ChannelSettings_psk_t k{};static const char lower[]="0123456789abcdef",upper[]="0123456789ABCDEF";bool hex=n==0 || n==2 || n==32 || n==64;
 if(hex){k.size=n/2;for(unsigned i=0;i<n;++i){auto p=std::strchr(lower,s[i]);auto q=std::strchr(upper,s[i]);if(!p && !q){hex=false;break;}auto v=p?p-lower:q-upper;k.bytes[i/2]|=v<<(i%2?0:4);}if(hex){out=k;return true;}}
 k={};static const char alphabet[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";unsigned bits=0,acc=0,padding=0;while(n && s[n-1]=='='){--n;++padding;}if(padding>2 || n%4==1 || (padding && (n+padding)%4))return false;
 for(unsigned i=0;i<n;++i){auto p=std::strchr(alphabet,s[i]);if(!p)return false;acc=(acc<<6)|unsigned(p-alphabet);bits+=6;if(bits>=8){bits-=8;if(k.size>=32)return false;k.bytes[k.size++]=(acc>>bits)&255;}}
 if((bits && (acc&((1u<<bits)-1))) || (k.size!=1 && k.size!=16 && k.size!=32))return false;out=k;return true;}
static void effective(meshtastic_ChannelSettings& s,const meshtastic_ChannelSettings& primary){channel_settings_resolve_inherited_key(&s,primary);if(s.psk.size==1 && s.psk.bytes[0]){auto index=s.psk.bytes[0];static const unsigned char key[]={0xd4,0xf1,0xbb,0x3a,0x20,0x29,0x07,0x59,0xf0,0xbc,0xff,0xab,0xcf,0x4e,0x69,0x01};s.psk.size=16;std::memcpy(s.psk.bytes,key,16);s.psk.bytes[15]+=index-1;}if(!s.psk.size){s.psk.size=1;s.psk.bytes[0]=0;}}
bool channel_plan_valid(const ChannelPlan& p){unsigned primaries=0;for(unsigned i=0;i<8;++i){auto& c=p.slots[i];if(c.index!=int(i) || unsigned(c.role)>2)return false;if(c.role){if(!c.has_settings || !channel_settings_valid(c.settings))return false;primaries+=c.role==meshtastic_Channel_Role_PRIMARY;}}return primaries==1;}
static const char* name(const meshtastic_ChannelSettings& s,const meshtastic_Config_LoRaConfig& l){if(s.name[0])return s.name;if(!l.use_preset)return "Custom";static const char* names[]={"LongFast","LongSlow","Invalid","MediumSlow","MediumFast","ShortSlow","ShortFast","LongMod","ShortTurbo","LongTurbo","Invalid","Invalid","Invalid","Invalid"};return names[unsigned(l.modem_preset)<14?unsigned(l.modem_preset):2];}
bool channel_plan_import(ChannelPlan& target,const meshtastic_ChannelSet& set,bool replace,bool radio){if(!set.settings_count || set.settings_count>8)return false;for(unsigned i=0;i<set.settings_count;++i)if(!channel_settings_valid(set.settings[i]))return false;ChannelPlan p=target;unsigned primary=0;for(unsigned i=0;i<8;++i)if(p.slots[i].role==meshtastic_Channel_Role_PRIMARY)primary=i;
 if(replace){for(unsigned i=0;i<8;++i){p.slots[i]={};p.slots[i].index=i;if(i<set.settings_count){p.slots[i].has_settings=true;p.slots[i].settings=set.settings[i];p.slots[i].role=i?meshtastic_Channel_Role_SECONDARY:meshtastic_Channel_Role_PRIMARY;}}}
 else for(unsigned i=0;i<set.settings_count;++i){auto proposed=set.settings[i];effective(proposed,set.settings[0]);if(!proposed.name[0]){auto resolved=name(proposed,set.has_lora_config?set.lora_config:p.lora);std::strcpy(proposed.name,resolved);}bool duplicate=false;for(auto& c:p.slots)if(c.role){auto e=c.settings;effective(e,p.slots[primary].settings);if(!std::strcmp(name(e,p.lora),proposed.name) && e.psk.size==proposed.psk.size && !std::memcmp(e.psk.bytes,proposed.psk.bytes,e.psk.size))duplicate=true;}if(duplicate)continue;unsigned free=8;for(unsigned j=0;j<8;++j)if(!p.slots[j].role){free=j;break;}if(free==8)return false;auto& c=p.slots[free];c.has_settings=true;c.role=meshtastic_Channel_Role_SECONDARY;c.settings=proposed;}
 for(auto& c:p.slots){c.settings.uplink_enabled=false;c.settings.downlink_enabled=false;}
 p.apply_lora=replace && radio && set.has_lora_config;if(p.apply_lora){auto& l=set.lora_config;if(!l.use_preset || unsigned(l.modem_preset)>13 || l.override_frequency || l.frequency_offset)return false;p.lora.use_preset=true;p.lora.modem_preset=l.modem_preset;p.lora.channel_num=l.channel_num;}
 if(!channel_plan_valid(p))return false;target=p;return true;}
